#include <stdio.h>

int sum_from(int fish[], int start, int count) {
    int sum = 0;
    for (int i = start; i < start + count; i++) {
        sum += fish[i];
    }
    return sum;
}

int main(void) {
    int fish[5] = { {a}, {b}, {c}, {d}, {e} };
    int sum = sum_from(fish, 0, 5);
    printf("总数是 %d\n", sum);
    return 0;
}
